/// <summary>
/// Class <c>METPOContinuingPermissionNoticeContract</c> contract
/// </summary>
 [
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(METPOContinuingPermissionNoticeContractUIBuilder))
 ]
class METPOContinuingPermissionNoticeContract implements SysOperationValidatable
{
    VendInvoiceId   vendInvoiceId;
    PurchId         purchId;
    METThreadCount  threadCount;
    boolean isAutoGenerateCPNotice = true;

}

Method.Source:
/// <summary>
/// Purchase order number parameter
/// </summary>
/// <param name = "_purchId">purchId</param>
/// <returns>purchId</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@SYS25204")),
    SysOperationControlVisibilityAttribute(false)

]
public PurchId parmPurchId(PurchId _purchId = purchId)
{
    purchId = _purchId;

    return purchId;
}

/// <summary>
/// Purchase order Invoice number parameter
/// </summary>
/// <param name = "_vendInvoiceId">InvoiceId</param>
/// <returns>InvoiceId</returns>
[
    DataMemberAttribute,
    SysOperationControlVisibilityAttribute(false)

]
public VendInvoiceId parmInvoiceId(VendInvoiceId _vendInvoiceId = vendInvoiceId)
{
    vendInvoiceId = _vendInvoiceId;

    return vendInvoiceId;
}

/// <summary>
/// Provides thread count parameter
/// </summary>
/// <param name = "_threadCount">Number of sub tasks spawned from main tasks</param>
/// <returns>The thread count</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
{
    threadCount = _threadCount;

    return threadCount;
}

/// <summary>
/// Gets or sets the flag indicating whether the Continuing Permission Notice (CPN) should be auto-generated.
/// </summary>
/// <param name="_isAutoGenerateCPNotice">
/// Optional. If provided, sets the internal flag to the given value.
/// </param>
/// <returns>
/// The current value of the isAutoGenerateCPNotice flag.
/// </returns>
/// <remarks>
/// This parameter is exposed in the SysOperation dialog and defaults to true.
/// </remarks>
[DataMember, SysOperationControlVisibilityAttribute(false), SysOperationLabelAttribute("@MET:GenerateAutoCP")]
public Boolean parmIsAutoGenerateCPNotice(Boolean _isAutoGenerateCPNotice = isAutoGenerateCPNotice)
{
    isAutoGenerateCPNotice = _isAutoGenerateCPNotice;

    return isAutoGenerateCPNotice;
}

/// <summary>
/// Validates the parameters.
/// </summary>
/// <returns>Is validated</returns>
public boolean validate()
{
    boolean isValid = true;

    if (threadCount < 0)
    {
        isValid = checkFailed("@MET:ThreadCountWarning");
    }

    return isValid;
}
